template <int N>
struct Factorial {
    // Recursive step
    static constexpr long value = N * Factorial<N - 1>::value;
};

template <>
struct Factorial<0> {
    // Base case specialization
    static constexpr long value = 1;
};

// Compile-time usage: No runtime calculation overhead
constexpr long result_5 = Factorial<5>::value; // 120

// Template parameter drives "function" selection
template <typename T>
struct SizeOfHelper {
    static constexpr size_t size = sizeof(T);
};

// Polymorphism via specialization for void*
template <>
struct SizeOfHelper<void*> {
    static constexpr size_t size = 8; // Assume 64-bit platform
};

constexpr size_t s_int = SizeOfHelper<int>::size;
constexpr size_t s_void = SizeOfHelper<void*>::size;
